      |> add_param(:body, :body, body)
      |> add_optional_params(optional_params, opts)
      |> finalize_request()
      |> Map.put(:opts, docspring_operation: "generateSubmissionFiles")
      |> Enum.into([])

    connection
    |> Connection.request(request)
    |> evaluate_response([
